const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([86.428836, 35.879797]);
  const aoi = point.buffer(50000); // 50 km radius
  const date = '2024-08-11';

  // The question asks for a future date. No satellite imagery will be available.
  // We will check for Sentinel-2 data to demonstrate this.
  const imageCollection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoi)
    .filterDate(date, ee.Date(date).advance(1, 'day'));

  // 2. Data Acquisition & Check
  const collectionSize = imageCollection.size().getInfo();

  if (collectionSize === 0) {
    console.log(`Image collection size for ${date}: 0`);
    console.log('Reason: The specified date is in the future, and no Earth observation data is available.');
    console.log('A: No'); // No lakes can be detected if no images exist.
  } else {
    // This block is unlikely to be executed but included for completeness.
    // 3. Processing
    const image = imageCollection.median().clip(aoi);

    // Using a pre-existing reliable water mask is better for identifying lakes.
    // JRC Global Surface Water dataset. 'occurrence' > 50 means water is present >50% of the time.
    const gsw = ee.Image('JRC/GSW1_4/GlobalSurfaceWater').select('occurrence');
    const waterMask = gsw.gt(50); // High-probability water bodies (lakes/rivers)

    // Identify connected components (individual water bodies)
    // Use a large pixel count to avoid counting small ponds. Let's say > 50 pixels (50 * 10*10m = 5000 sqm)
    const minLakeSizePixels = 50;
    const connections = waterMask.connectedPixelCount(minLakeSizePixels + 1, false);
    const lakes = waterMask.where(connections.lt(minLakeSizePixels), 0);

    // Count the number of distinct lakes
    const lakeObjects = lakes.connectedComponents({
        connectedness: ee.Kernel.plus(1),
        maxSize: 1024
    });

    const lakeCountDict = lakeObjects.select('labels').reduceRegion({
        reducer: ee.Reducer.countDistinct(),
        geometry: aoi,
        scale: 100,
        maxPixels: 1e9
    });

    // 4. Calculation
    const lakeCount = ee.Number(lakeCountDict.get('labels')).getInfo();

    if (lakeCount === null || typeof lakeCount === 'undefined') {
        console.log('Failed to calculate the number of lakes.');
        console.log('C3');
        return;
    }

    // 5. Validation & Final Answer
    console.log(`Images found for date: ${collectionSize}`);
    console.log(`Number of distinct lakes detected: ${lakeCount}`);

    if (lakeCount > 3) {
        console.log('A');
    } else {
        console.log('B');
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log('D');
});
